/// A provider's logo on a rounded tile (`size` in px).
pub fn logo(provider: &str, size: u32) -> String {
    let inner = size * 58 / 100;
    match provider {
        "aws" => {
            let w = size * 84 / 100;
            format!(r##"<span class="logo" style="width:{size}px;height:{size}px;background:#232F3E"><svg width="{w}" height="{w}" viewBox="0 0 24 24"><text x="12" y="13" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-weight="700" font-size="10.5" letter-spacing="-.3" fill="#fff">aws</text><path d="M4.6 15.6c4.8 2.9 10.1 2.9 14.8 0" fill="none" stroke="#FF9900" stroke-width="1.8" stroke-linecap="round"/><path d="M17.2 14.6l2.4.8-.7 2.3" fill="none" stroke="#FF9900" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg></span>"##)
        }
        "azure" => format!(r##"<span class="logo" style="width:{size}px;height:{size}px;background:#0078D4"><svg width="{inner}" height="{inner}" viewBox="0 0 24 24"><path d="M9.6 3h5.1L9.4 18.8 4 18.9 9.6 3Zm6 4.4 4.4 12.1H8.9l6.2-1.5-2.9-3.4 3.4-7.2Z" fill="#fff"/></svg></span>"##),
        p => match mark(p) {
            Some((path, color)) => {
                // Black marks follow the theme's ink, so they stay visible on dark.
                let fill = if ["#000000", "#181717", "#0B0D0E"].contains(&color) { "var(--ink)" } else { color };
                format!(r##"<span class="logo" style="width:{size}px;height:{size}px;background:color-mix(in srgb,{fill} 12%,var(--card))"><svg width="{inner}" height="{inner}" viewBox="0 0 24 24"><path d="{path}" fill="{fill}"/></svg></span>"##)
            }
            None => format!(r#"<span class="logo" style="width:{size}px;height:{size}px;background:var(--card-2)"></span>"#),
        },
    }
}

/// Small line icons (24×24, stroked with the text colour).
pub fn icon(name: &str) -> String {
    let d = match name {
        "lock" => "M6.5 10.5h11a1.5 1.5 0 0 1 1.5 1.5v7a1.5 1.5 0 0 1-1.5 1.5h-11A1.5 1.5 0 0 1 5 19v-7a1.5 1.5 0 0 1 1.5-1.5Zm2-.5V7.5a3.5 3.5 0 0 1 7 0V10",
        "check" => "m5 12.5 4.2 4.2L19 7",
        "plane" => "M4 7.5h16M4 12h16M4 16.5h10M17.5 16.5h2.5",
        "runners" => "M4.5 4.5h15a1 1 0 0 1 1 1v4a1 1 0 0 1-1 1h-15a1 1 0 0 1-1-1v-4a1 1 0 0 1 1-1Zm0 9h15a1 1 0 0 1 1 1v4a1 1 0 0 1-1 1h-15a1 1 0 0 1-1-1v-4a1 1 0 0 1 1-1ZM7 7.5h.01M7 16.5h.01",
        "jobs" => "M9 6h11M9 12h11M9 18h11M4.5 6h.01M4.5 12h.01M4.5 18h.01",
        "play" => "M8 5.5v13l10-6.5-10-6.5Z",
        "arrow" => "M5 12h14m-5-5 5 5-5 5",
        _ => "",
    };
    format!(r#"<svg class="ic" viewBox="0 0 24 24" aria-hidden="true"><path d="{d}"/></svg>"#)
}
